'use strict';

// MODULES //

var POLICY_PHRASES = require( './../policy_phrases.json' );


// FUNCTIONS //

/**
* Returns the output policy phrase environment variable.
*
* @private
* @param {string} policy - output policy
* @returns {string} environment variable string
*
* @example
* var envVar = outputPolicyPhraseEnvVar( 'floating_point_and_generic' );
* // returns 'a floating-point or "generic"'
*/
function outputPolicyPhraseEnvVar( policy ) {
	return POLICY_PHRASES[ policy ] || policy;
}

/**
* Returns the input policy phrase environment variable.
*
* @private
* @param {string} policy - input policy
* @returns {string} environment variable string
*
* @example
* var envVar = inputPolicyPhraseEnvVar( 'floating_point_and_generic' );
* // returns 'a floating-point or "generic"'
*/
function inputPolicyPhraseEnvVar( policy ) {
	return POLICY_PHRASES[ policy ] || policy;
}


// EXPORTS //

module.exports = {
	'outputPolicyPhraseEnvVar': outputPolicyPhraseEnvVar,
	'inputPolicyPhraseEnvVar': inputPolicyPhraseEnvVar
};
